      '• <b>الغياب بدون عذر:</b> يُرسل إشعار لولي الأمر، وتتاح الحصة التعويضية بنصف رسوم الحصة.',
      '• <b>مواعيد حصص التعويض الأسبوعية:</b>',
      '  - السبت (2:00 - 4:00 عصراً) — فرع مدينة نصر.',
      '  - الثلاثاء (4:00 - 6:00 مساءً) — فرع الدقي.'
    ].join('\n')
  };

  if (/غياب|غبت|تعويض|عذر|اعوض|أعوض|فاتتني|بديل|makeup|absence/i.test(query)) {
    return knowledge.makeup;
  } else if (/سعر|أسعار|اسعار|مصاريف|رسوم|اشتراك|اشتراكات|ملزمة|ملازم|كتاب|كتب|تكلفة|فلوس|بكام|كام|fee|price|booklet/i.test(query)) {
    return knowledge.fees;
  } else if (/مقر|مقرات|فرع|فروع|عنوان|عناوين|مكان|أماكن|مدينة نصر|الدقي|ارقام|أرقام|تواصل|تليفون|هاتف|لوكيشن|location|branch|address/i.test(query)) {
    return knowledge.locations;
  } else if (/مواعيد|موعد|جدول|حصة|حصص|كلاس|كلاسات|جمعة|احد|أحد|ثانوي|مجموعة|مجموعات|ساعة|وقت|schedule|time/i.test(query)) {
    return knowledge.schedules;
  } else {
    return [
      '🎓 <b>مرحباً بك في سنتر EduWise التعليمي!</b>',
      '═════════════════════════',
      'أنا مساعدك الذكي للإجابة عن كافة استفسارات السنتر.',
      '',
      '📌 يمكنك سؤالي عن:',
      '• <b>مواعيد الحصص:</b> لمراحل أولى وتانية وتالتة ثانوي.',
      '• <b>عناوين المقرات:</b> في مدينة نصر والدقي وأرقام التواصل.',
      '• <b>الأسعار والاشتراكات:</b> الشهرية وأسعار الملازم.',
      '• <b>سياسة الغياب:</b> ومواعيد حصص التعويض الأسبوعية.',
      '',
      '💬 <i>اكتب استفسارك وسأجيبك فوراً!</i>'
