const input = $('Route Private Telegram Message').first().json;
const candidate = $input.first().json.candidates?.[0];
const answer = candidate?.finishReason === 'STOP'
  ? (candidate.content?.parts ?? []).filter(p => !p.thought && typeof p.text === 'string')
    .map(p => p.text).join('').trim()
  : '';
